PRAGMA foreign_keys=ON;
CREATE TABLE workflow_templates (id TEXT PRIMARY KEY, namespace TEXT NOT NULL, version INTEGER NOT NULL CHECK(version > 0), body_digest TEXT NOT NULL, author_provenance_digest TEXT NOT NULL, created_at TEXT NOT NULL, UNIQUE(namespace, version), UNIQUE(namespace, body_digest));
CREATE TABLE workflow_template_roles (template_id TEXT NOT NULL REFERENCES workflow_templates(id), role_key TEXT NOT NULL, role_kind TEXT NOT NULL CHECK(role_kind IN ('human','agent')), purpose_digest TEXT NOT NULL, PRIMARY KEY(template_id, role_key));
CREATE TABLE workflow_inputs (id TEXT PRIMARY KEY, source_kind TEXT NOT NULL, source_id TEXT NOT NULL, source_digest TEXT NOT NULL, visibility_digest TEXT NOT NULL, UNIQUE(source_kind, source_id, source_digest));
CREATE TABLE workflow_runs (id TEXT PRIMARY KEY, template_id TEXT NOT NULL REFERENCES workflow_templates(id), expected_revision INTEGER NOT NULL CHECK(expected_revision > 0), envelope_digest TEXT NOT NULL, status TEXT NOT NULL CHECK(status IN ('draft','reviewing','complete','cancelled')));
CREATE TABLE workflow_run_inputs (run_id TEXT NOT NULL REFERENCES workflow_runs(id), input_id TEXT NOT NULL REFERENCES workflow_inputs(id), PRIMARY KEY(run_id, input_id));
CREATE TABLE workflow_attempts (id TEXT PRIMARY KEY, run_id TEXT NOT NULL REFERENCES workflow_runs(id), logical_work_id TEXT NOT NULL, predecessor_attempt_id TEXT REFERENCES workflow_attempts(id), task_id TEXT NOT NULL UNIQUE, session_id TEXT NOT NULL, actor_id TEXT NOT NULL, generation INTEGER NOT NULL CHECK(generation > 0), state TEXT NOT NULL, UNIQUE(run_id, logical_work_id, generation));
CREATE TABLE workflow_submissions (id TEXT PRIMARY KEY, run_id TEXT NOT NULL REFERENCES workflow_runs(id), author_attempt_id TEXT NOT NULL REFERENCES workflow_attempts(id), revision INTEGER NOT NULL, bytes_digest TEXT NOT NULL, maker_id TEXT NOT NULL, UNIQUE(run_id, revision), UNIQUE(run_id, bytes_digest));
CREATE TABLE workflow_rounds (id TEXT PRIMARY KEY, submission_id TEXT NOT NULL UNIQUE REFERENCES workflow_submissions(id), generation INTEGER NOT NULL CHECK(generation > 0), state TEXT NOT NULL, expected_revision INTEGER NOT NULL CHECK(expected_revision > 0));
CREATE TABLE workflow_review_requests (id TEXT PRIMARY KEY, round_id TEXT NOT NULL REFERENCES workflow_rounds(id), reviewer_attempt_id TEXT REFERENCES workflow_attempts(id), slot TEXT NOT NULL, authority_digest TEXT NOT NULL, generation INTEGER NOT NULL CHECK(generation > 0), status TEXT NOT NULL CHECK(status IN ('pending','approved','changes_requested','closed')), UNIQUE(round_id, slot, generation));
CREATE TABLE workflow_review_receipts (id TEXT PRIMARY KEY, request_id TEXT NOT NULL REFERENCES workflow_review_requests(id), submission_digest TEXT NOT NULL, reviewer_id TEXT NOT NULL, outcome TEXT NOT NULL CHECK(outcome IN ('approved','changes_requested')), result_digest TEXT NOT NULL, created_at TEXT NOT NULL, UNIQUE(request_id, submission_digest, reviewer_id));
CREATE TABLE workflow_operation_replays (scope TEXT NOT NULL, operation_key TEXT NOT NULL, request_digest TEXT NOT NULL, receipt_digest TEXT NOT NULL, PRIMARY KEY(scope, operation_key));
CREATE TABLE workflow_effects (id TEXT PRIMARY KEY, run_id TEXT NOT NULL REFERENCES workflow_runs(id), operation_scope TEXT NOT NULL, operation_key TEXT NOT NULL, effect_kind TEXT NOT NULL, task_id TEXT, delivery_state TEXT NOT NULL, UNIQUE(operation_scope, operation_key, effect_kind));
CREATE INDEX workflow_runs_template_idx ON workflow_runs(template_id);
CREATE INDEX workflow_submissions_run_revision_idx ON workflow_submissions(run_id, revision);
CREATE INDEX workflow_attempts_run_state_idx ON workflow_attempts(run_id, state);
CREATE INDEX workflow_review_requests_round_idx ON workflow_review_requests(round_id);
CREATE INDEX workflow_effects_run_delivery_idx ON workflow_effects(run_id, delivery_state);
